<?php require_once __DIR__.'/../includes/permissions.php'; ?>
<?php require_role('buyer');$s=db()->prepare('SELECT r.*,p.name product_name,o.order_number FROM reviews r JOIN products p ON p.id=r.product_id LEFT JOIN orders o ON o.id=r.order_id WHERE r.user_id=? ORDER BY r.created_at DESC');$s->execute([user()['id']]);$reviews=$s->fetchAll();
$s=db()->prepare('SELECT oi.order_id,oi.product_id,oi.product_name,o.order_number,o.updated_at FROM order_items oi JOIN orders o ON o.id=oi.order_id LEFT JOIN reviews r ON r.order_id=oi.order_id AND r.product_id=oi.product_id AND r.user_id=? WHERE o.buyer_id=? AND oi.status<>"cancelled" AND (oi.status="delivered" OR o.status="delivered") AND r.id IS NULL GROUP BY oi.order_id,oi.product_id,oi.product_name,o.order_number,o.updated_at ORDER BY o.updated_at DESC');$s->execute([user()['id'],user()['buyer_id']]);$pending=$s->fetchAll();include __DIR__.'/../includes/header.php';?><div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php';?><section class="dashboard-content"><div class="dashboard-top"><div><span class="eyebrow">A sua opinião</span><h1>Avaliações</h1></div></div>
<div class="content-card mb-4"><div class="card-heading"><h4>Por avaliar</h4><span class="small text-muted"><?=count($pending)?> produto(s)</span></div><?php if(!$pending): ?><p class="text-muted mb-0">Não tem produtos entregues por avaliar.</p><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Produto</th><th>Pedido</th><th></th></tr></thead><tbody><?php foreach($pending as $p):?><tr><td><?=e($p['product_name'])?></td><td><?=e($p['order_number'])?></td><td class="text-end"><a class="btn btn-sm btn-primary" href="<?=base_path('comprador/pedido-detalhes.php?id='.safe_int($p['order_id']))?>"><i class="bi bi-star me-1"></i>Avaliar</a></td></tr><?php endforeach;?></tbody></table></div><?php endif; ?></div>
<div class="content-card"><div class="card-heading"><h4>As minhas avaliações</h4></div><?php if(!$reviews): ?><p class="text-muted mb-0">Ainda não fez avaliações.</p><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Produto</th><th>Pedido</th><th>Nota</th><th>Comentário</th><th>Data</th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><a href="<?=base_path('produto.php?id='.safe_int($r['product_id']))?>"><?=e($r['product_name'])?></a><?php if(($r['status']??'visible')==='hidden'): ?> <span class="badge text-bg-secondary">Oculta pela moderação</span><?php endif; ?></td><td><?=e($r['order_number']??'—')?></td><td><span class="rating" aria-label="<?=safe_int($r['rating'])?> de 5 estrelas"><?=str_repeat('<i class="bi bi-star-fill" aria-hidden="true"></i>',safe_int($r['rating']))?></span></td><td><?=e($r['comment'])?></td><td><?=date('d/m/Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif; ?></div></section></div><?php include __DIR__.'/../includes/footer.php';?>
